import{_ as a,C as n,o as s,c as i,E as o,a2 as r}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Weekly 008 — Authority Is a Relation, Not an Attribute","description":"","frontmatter":{"title":"Weekly 008 — Authority Is a Relation, Not an Attribute","date":"2026-09-06","column":"digital-employee","category":"weekly","article_type":"research-brief","edition":"research-center","research_question":"When an agent is about to act, which facts must be bound together before we can say that this particular action is actually authorized?","summary":"Fifteen published Daily Research notes from August 31 through September 6 repeatedly expose the same boundary: installed, approved, trusted, verified, checkpointed, or stable identity are not execution authority that can simply be inherited. A stronger model treats authority as a relation among principal, action, target, occurrence, protocol, policy epoch, and evidence, re-evaluated before consequential execution.","sources":["2026-08-31 through 2026-09-06 Daily Runtime V5 publications","research/intelligence/p2-runs/2026/09/2026-09-06-p2-special.json"],"evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"cover":"/assets/covers/weekly-008-authority-is-a-relation-editorial-v3.webp"},"headers":[],"relativePath":"en/research/weekly/weekly-008.md","filePath":"en/research/weekly/weekly-008.md","lastUpdated":1788755595000}'),l={name:"en/research/weekly/weekly-008.md"};function p(c,e,d,h,u,m){const t=n("ArticleCover");return s(),i("div",null,[o(t,{image:"/assets/covers/weekly-008-authority-is-a-relation-editorial-v3.webp",kicker:"Weekly Research · 008",title:"Authority Is a Relation, Not an Attribute",summary:"Identity, approvals, and state can persist. Execution authority must still hold for this principal, action, target, and occurrence.",version:"W008",status:"Published 2026-09-06",languageHref:"/zh/research/weekly/weekly-008",languageLabel:"中文"}),e[0]||(e[0]=r(`<h1 id="weekly-008-—-authority-is-a-relation-not-an-attribute" tabindex="-1">Weekly 008 — Authority Is a Relation, Not an Attribute <a class="header-anchor" href="#weekly-008-—-authority-is-a-relation-not-an-attribute" aria-label="Permalink to &quot;Weekly 008 — Authority Is a Relation, Not an Attribute&quot;">​</a></h1><p>A connector is installed. An agent has a role. A workspace is marked trusted. An approval was recorded. A checkpoint is recoverable. Credential discovery found an endpoint. A stable identity exists.</p><p>Each statement can be true. The mistake begins when those truths are silently compressed into one stronger conclusion: <em>therefore this action may execute now</em>.</p><p>Daily Research from August 31 through September 6 reached the same boundary from standing permissions, working memory, connectors, checkpoints, delegation, OAuth discovery, human approval, recovery, and stable identity: <strong>a descriptive fact about an object is easy to mistake for execution authority over a particular action.</strong></p><p>Weekly 007 concluded that recovery is not restoration; it is re-admission. Reconstructed state has to re-establish current authority, ownership, occurrence identity, and replay integrity before execution resumes. This week shows that the principle is not limited to recovery. The same boundary appears during ordinary installation, connection, delegation, approval, credential resolution, and tool use.</p><p>The broader judgment is therefore:</p><blockquote><p><strong>Authority is better modelled as a relation than as a static attribute attached to a user, agent, tool, connector, checkpoint, or credential.</strong></p></blockquote><p>Instead of asking only:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>is_admin = true?</span></span>
<span class="line"><span>connector_installed = true?</span></span>
<span class="line"><span>approved = true?</span></span>
<span class="line"><span>trusted = true?</span></span>
<span class="line"><span>checkpoint_valid = true?</span></span></code></pre></div><p>a runtime needs to answer a more specific question:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>May this principal,</span></span>
<span class="line"><span>under the current policy epoch,</span></span>
<span class="line"><span>perform this action,</span></span>
<span class="line"><span>on this target,</span></span>
<span class="line"><span>for this occurrence,</span></span>
<span class="line"><span>through this protocol,</span></span>
<span class="line"><span>using this current evidence?</span></span></code></pre></div><p>The second question is much closer to what &quot;authorized&quot; actually means at execution time.</p><h2 id="evidence-scope-seven-runtime-days-fifteen-published-studies" tabindex="-1">Evidence scope: seven runtime days, fifteen published studies <a class="header-anchor" href="#evidence-scope-seven-runtime-days-fifteen-published-studies" aria-label="Permalink to &quot;Evidence scope: seven runtime days, fifteen published studies&quot;">​</a></h2><p>This synthesis uses only Daily Research whose Runtime lifecycle closed from <strong>2026-08-31 through 2026-09-06</strong>. All seven days completed Publication. September 1 was a governed zero-output day: Production produced no eligible Publication Candidate, and Publication released nothing rather than manufacturing an article. The other six days produced <strong>15</strong> Research Center studies.</p><table tabindex="0"><thead><tr><th>Date</th><th>Digital Employee</th><th>Industry Architecture</th><th>Open-source Engineering</th></tr></thead><tbody><tr><td>8/31</td><td>A standing rule is not this action&#39;s authority</td><td>A reconstructed role is not proof of authority</td><td>A successful rerun does not prove the repair</td></tr><tr><td>9/1</td><td>—</td><td>—</td><td>—</td></tr><tr><td>9/2</td><td>Token budget is not working-memory evidence</td><td>Installed is not authorized</td><td>A smaller skill is not the same skill</td></tr><tr><td>9/3</td><td>A checkpoint is not a recovery contract</td><td>Delegation is a stateful authorization program</td><td>Discovery must not redefine credential authority</td></tr><tr><td>9/4</td><td>—</td><td>—</td><td>Recovery evidence is not replay authority</td></tr><tr><td>9/5</td><td>Judgment is not effective approval</td><td>—</td><td>Passing tests is not operational capability</td></tr><tr><td>9/6</td><td>Risk does not choose protocol</td><td>Recovery is a trajectory</td><td>Stable identity does not authorize destination</td></tr></tbody></table><p>These are not fifteen restatements of one vendor event. They examine human supervision, context reconstruction, connector authority, skill compression, delegation chains, credential discovery, approval, replay, operational capability, and destination binding. The value of the weekly synthesis comes from the recurrence of the same semantic failure across different mechanisms.</p><h2 id="the-attribute-trap-true-facts-becoming-unauthorized-implications" tabindex="-1">The attribute trap: true facts becoming unauthorized implications <a class="header-anchor" href="#the-attribute-trap-true-facts-becoming-unauthorized-implications" aria-label="Permalink to &quot;The attribute trap: true facts becoming unauthorized implications&quot;">​</a></h2><p>The most dangerous authorization errors do not always look like <code>allow_all</code>. They often begin with facts that are individually correct and become wrong only when the system upgrades their meaning during composition.</p><p>Consider:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>connector is installed</span></span>
<span class="line"><span>→ agent has connector capability</span></span>
<span class="line"><span>→ agent may access the target resource</span></span></code></pre></div><p>The September 2 Industry Architecture study separates those propositions. Administrative availability, configured agent capability, the acting principal or account, target-resource permission, and runtime policy are distinct. A connector appearing in the system proves that an entry point exists. It does not establish that the current principal may perform the requested operation against the current target.</p><p>Or consider:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>the AI judges that approval is appropriate</span></span>
<span class="line"><span>→ effective authorization has been granted</span></span></code></pre></div><p>The September 5 Digital Employee study separates approval assessment from sign-off authority that can actually change target-system state. A model may recommend approval; authority-bearing approval still needs a principal, a scope, and a validity boundary.</p><p>Or:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a stable identity has been established</span></span>
<span class="line"><span>→ that identity may be used against any destination</span></span></code></pre></div><p>The September 6 Engineering study shows why identity stability only addresses continuity of <em>who</em> the subject is. It does not answer what that subject may do to a particular destination. If resource, issuer, audience, or policy context changes, a stable identity does not create a new authorization relation by itself.</p><p>Across these examples, the common rule is:</p><blockquote><p><strong>Object attributes are inputs to an authority decision; they are not authority itself.</strong></p></blockquote><h2 id="three-fact-planes-should-remain-separate" tabindex="-1">Three fact planes should remain separate <a class="header-anchor" href="#three-fact-planes-should-remain-separate" aria-label="Permalink to &quot;Three fact planes should remain separate&quot;">​</a></h2><p>A reliable agent runtime benefits from preserving at least three classes of fact rather than flattening them into one status field.</p><h3 id="_1-descriptive-facts" tabindex="-1">1. Descriptive facts <a class="header-anchor" href="#_1-descriptive-facts" aria-label="Permalink to &quot;1. Descriptive facts&quot;">​</a></h3><p>These answer <em>what exists now</em>:</p><ul><li>a connector is installed;</li><li>a skill is loaded;</li><li>a checkpoint exists;</li><li>a principal identity has been resolved;</li><li>a workspace has a trust state;</li><li>an approval record exists.</li></ul><p>They are important state facts. They are not normally sufficient to drive a consequential action directly.</p><h3 id="_2-evidence-facts" tabindex="-1">2. Evidence facts <a class="header-anchor" href="#_2-evidence-facts" aria-label="Permalink to &quot;2. Evidence facts&quot;">​</a></h3><p>These answer <em>why the system believes a state or judgment</em>:</p><ul><li>which issuer established an identity;</li><li>which occurrence produced a checkpoint;</li><li>who issued an approval, when, and for what object;</li><li>which call a tool result belongs to;</li><li>whether recovery evidence comes from the same authoritative history;</li><li>exactly what environment and condition a passing test exercised.</li></ul><p>The September 5 Engineering study, &quot;Passing Tests Is Not Operational Capability,&quot; is a useful example. Tests can be strong evidence, but only when their coverage boundary is known. A <code>PASS</code> label by itself is not a capability fact.</p><h3 id="_3-authority-facts" tabindex="-1">3. Authority facts <a class="header-anchor" href="#_3-authority-facts" aria-label="Permalink to &quot;3. Authority facts&quot;">​</a></h3><p>This is the narrowest and most dynamic plane:</p><blockquote><p><strong>Under the current conditions, may this principal perform this action against this target?</strong></p></blockquote><p>It consumes descriptive and evidentiary facts, but it should not simply copy them.</p><p>A useful abstraction is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authority = Admit(</span></span>
<span class="line"><span>  principal,</span></span>
<span class="line"><span>  action,</span></span>
<span class="line"><span>  target,</span></span>
<span class="line"><span>  occurrence,</span></span>
<span class="line"><span>  protocol,</span></span>
<span class="line"><span>  policy_epoch,</span></span>
<span class="line"><span>  evidence</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>When a material dimension changes, an old decision should not be silently assumed to remain valid.</p><h2 id="principal-a-role-label-is-not-a-substitute-for-authority" tabindex="-1">Principal: a role label is not a substitute for authority <a class="header-anchor" href="#principal-a-role-label-is-not-a-substitute-for-authority" aria-label="Permalink to &quot;Principal: a role label is not a substitute for authority&quot;">​</a></h2><p>The August 31 Industry Architecture study examines context reconstruction. If attacker-controlled or otherwise lower-privilege content is reconstructed into a higher-authority instruction position, a later permission reviewer can reason correctly about risk while reasoning from a corrupted authority premise.</p><p>Principal therefore cannot be only a string or role label. A runtime needs to know at least:</p><ul><li>who the current actor is;</li><li>who minted or verified that identity;</li><li>where the current role came from;</li><li>whether it is still valid;</li><li>whether worker replacement, account switching, or delegation occurred.</li></ul><p>If a system serializes <code>role=admin</code>, reloads it after recovery, and treats the restored string as sufficient authority, it has preserved a descriptive value rather than current authorization.</p><h2 id="action-one-tool-does-not-imply-one-authorization-scope" tabindex="-1">Action: one tool does not imply one authorization scope <a class="header-anchor" href="#action-one-tool-does-not-imply-one-authorization-scope" aria-label="Permalink to &quot;Action: one tool does not imply one authorization scope&quot;">​</a></h2><p>Standing permission encourages overly coarse action models.</p><p>The August 31 Digital Employee study distinguishes user-authored permission policy from occurrence-specific runtime commitment. Reusable rules can reduce repeated prompts, but the study&#39;s participant data also shows many category rules preserving an explicit <code>Ask</code> boundary. Users themselves often distinguish a standing preference from committing a particular consequential action.</p><p>So:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GitHub use is allowed</span></span></code></pre></div><p>should not naturally expand into:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>deleting this repository is allowed</span></span>
<span class="line"><span>merging this pull request is allowed</span></span>
<span class="line"><span>writing this branch is allowed</span></span>
<span class="line"><span>acting for this account on this operation is allowed</span></span></code></pre></div><p>The runtime needs action semantics fine-grained enough that a tool name does not carry the entire authorization meaning.</p><h2 id="target-capability-entry-point-and-resource-authority-are-different-propositions" tabindex="-1">Target: capability entry point and resource authority are different propositions <a class="header-anchor" href="#target-capability-entry-point-and-resource-authority-are-different-propositions" aria-label="Permalink to &quot;Target: capability entry point and resource authority are different propositions&quot;">​</a></h2><p>&quot;Installed Is Not Authorized&quot; on September 2 and &quot;Stable Identity Does Not Authorize Destination&quot; on September 6 approach the same boundary from different sides: <strong>target identity is part of authority.</strong></p><p>Knowing that an agent can call a connector only establishes connector capability. The actual target can be:</p><ul><li>one mailbox;</li><li>one GitHub repository;</li><li>one calendar;</li><li>one internal database;</li><li>one MCP server;</li><li>a specific object inside a resource.</li></ul><p>A target change can change the authority relation. Push access to repository A cannot safely be inherited by repository B merely because &quot;GitHub is connected.&quot;</p><h2 id="occurrence-the-same-task-happening-again-is-not-the-same-authorization-event" tabindex="-1">Occurrence: the same task happening again is not the same authorization event <a class="header-anchor" href="#occurrence-the-same-task-happening-again-is-not-the-same-authorization-event" aria-label="Permalink to &quot;Occurrence: the same task happening again is not the same authorization event&quot;">​</a></h2><p>Several recovery studies this week emphasize occurrence identity.</p><p>The September 3 checkpoint work separates reconstructing state from identifying the exact execution instance that state belongs to. September 4 goes further: recovery evidence does not automatically become replay authority. If a previous tool call may already have happened, if the effect is unknown, or if an approval covered only a particular interruption point, a new worker cannot replay simply because it can read the old state.</p><p>The authority relation therefore needs a way to identify the concrete occurrence, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>workflow_id</span></span>
<span class="line"><span>+ branch_id</span></span>
<span class="line"><span>+ occurrence_id</span></span></code></pre></div><p>or an equivalent composite identity.</p><p>That lets the runtime ask whether an approval authorized an action class in general or only one still-unexecuted occurrence.</p><h2 id="protocol-risk-magnitude-should-not-choose-authorization-protocol-by-itself" tabindex="-1">Protocol: risk magnitude should not choose authorization protocol by itself <a class="header-anchor" href="#protocol-risk-magnitude-should-not-choose-authorization-protocol-by-itself" aria-label="Permalink to &quot;Protocol: risk magnitude should not choose authorization protocol by itself&quot;">​</a></h2><p>The September 6 Digital Employee research establishes another subtle boundary: risk scores can influence review intensity without being sufficient to select the protocol.</p><p>The same high-consequence operation may require different mechanisms in different environments:</p><ul><li>a runtime prompt;</li><li>human approval;</li><li>OAuth or delegated consent;</li><li>a host-minted capability;</li><li>two-person control;</li><li>or complete prohibition.</li></ul><p>Protocol choice should depend on authority context, action type, target, policy, and available system mechanism. A risk score alone should not map directly to &quot;auto-allow&quot; or &quot;auto-deny.&quot;</p><p>This also explains the September 3 Engineering conclusion that discovery must not redefine credential authority. Discovery may tell a client where authorization services are located. It should not allow a redirect, metadata path, or lower-trust discovery input to redefine who the authoritative issuer is.</p><h2 id="policy-epoch-old-allow-decisions-need-an-invalidation-story" tabindex="-1">Policy epoch: old allow decisions need an invalidation story <a class="header-anchor" href="#policy-epoch-old-allow-decisions-need-an-invalidation-story" aria-label="Permalink to &quot;Policy epoch: old allow decisions need an invalidation story&quot;">​</a></h2><p>Permissions can be revoked. Workspace trust can change. Resource ACLs can change. Accounts can switch. In such systems, a permanent <code>approved=true</code> is almost certainly too weak a representation.</p><p>An authority relation needs a policy epoch or equivalent version identity so the runtime can answer:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Does this old allow decision</span></span>
<span class="line"><span>still belong to the current policy world?</span></span></code></pre></div><p>This extends Weekly 007&#39;s re-admission argument beyond crash recovery. Even when there is no failure or resume event, a material change in authority context should force a new evaluation of any decision that depended on the old context.</p><h2 id="recovery-is-a-trajectory-not-a-snapshot" tabindex="-1">Recovery is a trajectory, not a snapshot <a class="header-anchor" href="#recovery-is-a-trajectory-not-a-snapshot" aria-label="Permalink to &quot;Recovery is a trajectory, not a snapshot&quot;">​</a></h2><p>The September 6 Industry Architecture study adds time to the relation model. Recovery is not a jump from one static state to another. It is a trajectory with multiple transition points:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>state loaded</span></span>
<span class="line"><span>→ evidence reconciled</span></span>
<span class="line"><span>→ old ownership closed</span></span>
<span class="line"><span>→ authority refreshed</span></span>
<span class="line"><span>→ occurrence rebound</span></span>
<span class="line"><span>→ capability materialized</span></span>
<span class="line"><span>→ action resumed</span></span></code></pre></div><p>Authority is not a token pulled out of a checkpoint at the beginning of that sequence. Its value can differ at different transition points.</p><p>That is why the September 4 Engineering study separates recovery evidence from replay authority. The system may know what happened before and still lack permission to do it again now.</p><p>A stricter recovery model is therefore not:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>checkpoint.valid == true</span></span>
<span class="line"><span>→ resume</span></span></code></pre></div><p>but:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reconstruct</span></span>
<span class="line"><span>→ reconcile facts</span></span>
<span class="line"><span>→ close or transfer ownership</span></span>
<span class="line"><span>→ re-evaluate authority relation</span></span>
<span class="line"><span>→ materialize capability</span></span>
<span class="line"><span>→ resume bounded occurrence</span></span></code></pre></div><h2 id="convenient-proxies-do-not-automatically-preserve-governed-meaning" tabindex="-1">Convenient proxies do not automatically preserve governed meaning <a class="header-anchor" href="#convenient-proxies-do-not-automatically-preserve-governed-meaning" aria-label="Permalink to &quot;Convenient proxies do not automatically preserve governed meaning&quot;">​</a></h2><p>Three studies this week are not primarily about authorization, yet they strengthen the same relation-oriented reasoning.</p><h3 id="token-budget-is-not-working-memory-evidence" tabindex="-1">Token budget is not working-memory evidence <a class="header-anchor" href="#token-budget-is-not-working-memory-evidence" aria-label="Permalink to &quot;Token budget is not working-memory evidence&quot;">​</a></h3><p>The September 2 Digital Employee study finds that equal token budgets do not imply equal delivered context or equal memory-management cost. A convenient measurable proxy cannot simply replace the proposition the system actually needs to govern.</p><h3 id="a-smaller-skill-is-not-the-same-skill" tabindex="-1">A smaller skill is not the same skill <a class="header-anchor" href="#a-smaller-skill-is-not-the-same-skill" aria-label="Permalink to &quot;A smaller skill is not the same skill&quot;">​</a></h3><p>The same day&#39;s Engineering study finds that skill compression can break routing or public callable-entry contracts. Shorter text is not sufficient evidence of semantic equivalence. Equivalence has to be checked at the relation boundary where the capability is invoked.</p><h3 id="passing-tests-is-not-operational-capability" tabindex="-1">Passing tests is not operational capability <a class="header-anchor" href="#passing-tests-is-not-operational-capability" aria-label="Permalink to &quot;Passing tests is not operational capability&quot;">​</a></h3><p>The September 5 Engineering study makes the parallel explicit for testing. A passing test has to remain bound to environment, entry point, dependencies, and execution conditions. Otherwise <code>PASS</code> becomes another incomplete evidence attribute.</p><p>All three have the same structure as authority: <strong>do not upgrade an easy-to-store, easy-to-display, easy-to-compute attribute into the stronger governed proposition it merely proxies.</strong></p><h2 id="an-implementable-abstraction-the-authority-relation-envelope" tabindex="-1">An implementable abstraction: the Authority Relation Envelope <a class="header-anchor" href="#an-implementable-abstraction-the-authority-relation-envelope" aria-label="Permalink to &quot;An implementable abstraction: the Authority Relation Envelope&quot;">​</a></h2><p>The week&#39;s evidence can be compressed into a more useful minimum record than <code>approved=true</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AuthorityRelationEnvelope</span></span>
<span class="line"><span>├─ principal</span></span>
<span class="line"><span>│  ├─ subject_id</span></span>
<span class="line"><span>│  ├─ issuer / account</span></span>
<span class="line"><span>│  └─ delegated_from</span></span>
<span class="line"><span>├─ action</span></span>
<span class="line"><span>│  ├─ capability</span></span>
<span class="line"><span>│  └─ operation</span></span>
<span class="line"><span>├─ target</span></span>
<span class="line"><span>│  ├─ resource_id</span></span>
<span class="line"><span>│  └─ destination / audience</span></span>
<span class="line"><span>├─ occurrence</span></span>
<span class="line"><span>│  ├─ workflow_id</span></span>
<span class="line"><span>│  ├─ branch_id</span></span>
<span class="line"><span>│  └─ occurrence_id</span></span>
<span class="line"><span>├─ protocol</span></span>
<span class="line"><span>│  ├─ approval_type</span></span>
<span class="line"><span>│  └─ credential / capability path</span></span>
<span class="line"><span>├─ policy</span></span>
<span class="line"><span>│  ├─ policy_epoch</span></span>
<span class="line"><span>│  └─ trust context</span></span>
<span class="line"><span>├─ evidence</span></span>
<span class="line"><span>│  ├─ source refs</span></span>
<span class="line"><span>│  ├─ decision refs</span></span>
<span class="line"><span>│  └─ verification refs</span></span>
<span class="line"><span>└─ result</span></span>
<span class="line"><span>   ├─ admitted / denied / paused</span></span>
<span class="line"><span>   ├─ issued_at</span></span>
<span class="line"><span>   └─ expires / invalidation rule</span></span></code></pre></div><p>This is not an argument that every low-risk action needs a large JSON record. It identifies dimensions that should not be collapsed architecturally into one Boolean. Implementations can cache, index, compress, or derive them as long as relation identity and invalidation conditions remain recoverable.</p><h2 id="dynamic-authority-does-not-mean-asking-a-human-on-every-call" tabindex="-1">Dynamic authority does not mean asking a human on every call <a class="header-anchor" href="#dynamic-authority-does-not-mean-asking-a-human-on-every-call" aria-label="Permalink to &quot;Dynamic authority does not mean asking a human on every call&quot;">​</a></h2><p>Treating authority as a relation does not require turning an agent system into an approval-dialog factory.</p><p>If a class of operation preserves:</p><ul><li>the same principal;</li><li>the same action scope;</li><li>a bounded target set;</li><li>the same policy epoch;</li><li>a protocol that explicitly permits reuse;</li><li>occurrence reuse that matches the contract;</li><li>and a grant that has not expired or been revoked;</li></ul><p>then the runtime can reuse a bounded authority relation without prompting again.</p><p>The important distinction is:</p><blockquote><p><strong>What gets reused should be a scoped relation with identity and invalidation rules, not a context-free <code>approved=true</code>.</strong></p></blockquote><h2 id="what-the-evidence-does-not-establish-yet" tabindex="-1">What the evidence does not establish yet <a class="header-anchor" href="#what-the-evidence-does-not-establish-yet" aria-label="Permalink to &quot;What the evidence does not establish yet&quot;">​</a></h2><p>The week&#39;s evidence supports the relation model as an engineering abstraction. It does <strong>not</strong> establish one universal authorization protocol for all agent systems.</p><p>Open questions include:</p><ul><li>how fine-grained action identity should be at different risk levels;</li><li>which authority relations can be cached safely, and for how long;</li><li>how to compress principal chains in deep multi-agent delegation without losing constraints;</li><li>how much protocol should be shared across external SaaS, MCP, local tools, and native apps;</li><li>the minimum interoperable representation of policy epoch, occurrence identity, and target identity.</li></ul><p>The September 2 connector study itself did not find evidence for a universal end-to-end authorization protocol. The relation model is a claim about <strong>which semantics should be preserved</strong>, not a claim that one standard implementation already exists.</p><h2 id="p2-one-special-study-triggered-but-it-is-not-imported-into-the-public-argument" tabindex="-1">P2: one special study triggered, but it is not imported into the public argument <a class="header-anchor" href="#p2-one-special-study-triggered-but-it-is-not-imported-into-the-public-argument" aria-label="Permalink to &quot;P2: one special study triggered, but it is not imported into the public argument&quot;">​</a></h2><p>This week&#39;s P2 lane resolved <strong>6/6</strong> due objects. <code>yzhao062/pyod</code> <code>v3.6.5</code> showed a material benchmark/evaluation change relative to the previous monthly checkpoint, scored 9/10, and therefore triggered the one full P2 Special Study permitted for this run. The internal result is an <code>Experiment Candidate</code>.</p><p>That study is still a <strong>Pending Review</strong> internal research asset. Under the P2 publication boundary, completion of Weekly does not turn it into a public article, and its internal mechanism result is not used as public evidence for the Authority Relation thesis above. It is reported here only as workflow state: P2 found a benchmark-validity question worth a bounded experiment; public promotion would require a separate review and the normal reading, analysis, evidence, writing, and editing gates.</p><p>Aegis and agent-style changed during the interval but not in the mechanisms declared by their P2 triggers. agent-audit, cs-paper-checklist, and anomaly-detection-resources showed no material checkpoint change.</p><h2 id="four-useful-tests-for-next-week" tabindex="-1">Four useful tests for next week <a class="header-anchor" href="#four-useful-tests-for-next-week" aria-label="Permalink to &quot;Four useful tests for next week&quot;">​</a></h2><p>The relation model is now specific enough to be falsifiable rather than rhetorical.</p><p>First, test an <strong>authority cache</strong>. Cache a grant that binds principal, action, target, and policy epoch. Change target, account, and policy epoch separately. Verify that materially changed relations invalidate the old grant while unchanged relations can still reuse it safely.</p><p>Second, test <strong>delegation composition</strong>. Delegate through three agent layers and verify that each step can only preserve or narrow action and target scope, while cumulative constraints remain traceable to the root objective.</p><p>Third, test a <strong>recovery transition</strong>. Interrupt once before a tool call, once after effect commit but before the response arrives, and once while human approval is pending. Verify that recovery distinguishes &quot;restore context,&quot; &quot;reconcile authoritative history first,&quot; and &quot;wait for new authorization&quot; as different relation states.</p><p>Fourth, test <strong>protocol selection</strong>. Hold the action constant while varying target, risk, credential path, and policy context. Verify that risk changes review intensity but does not by itself choose the authorization protocol.</p><p>If those tests show that a simple object-level flag preserves the same safety semantics across all of these changes, the relation model should be narrowed. If failures cluster where relation dimensions are lost or reused incorrectly, the abstraction gains stronger engineering support.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Recent Weekly research has repeatedly separated concepts that look similar but carry different authority: state is not permission; evidence is not authorization; recovery is not restoration; lineage is not current admission.</p><p>This week compresses those separations into a more general design principle:</p><blockquote><p><strong>Authority is not a permanent property describing what an object possesses. It is a relational judgment about whether this principal may perform this action against this target under the current conditions.</strong></p></blockquote><p>Identity, connector state, checkpoints, approvals, trust, test results, and risk scores can all provide evidence or inputs to that relation. None should substitute for the relation by itself.</p><p>For long-lived agents, digital employees, and multi-agent runtimes, the distinction determines whether the system merely remembers what was allowed sometime in the past—or can answer the harder question immediately before action: <em>is this principal still allowed to do this thing, here, now?</em></p>`,133))])}const b=a(l,[["render",p]]);export{g as __pageData,b as default};
